input.command:
cat > auth.js <<'EOF'
const crypto = require("crypto");

// Session check for admin routes: a signed cookie set by /login.
function requireLogin(req, res, next) {
  if (req.headers.cookie && /session=/.test(req.headers.cookie)) return next();
  res.status(401).json({ error: "login required" });
}

// For scripts: accept a matching x-api-key header, otherwise fall back to login.
// Disabled unless REPORTS_API_KEY is set.
function requireApiKeyOrLogin(req, res, next) {
  const expected = process.env.REPORTS_API_KEY;
  const given = req.headers["x-api-key"];
  if (expected && typeof given === "string") {
    const a = Buffer.from(given);
    const b = Buffer.from(expected);
    if (a.length === b.length && crypto.timingSafeEqual(a, b)) return next();
  }
  return requireLogin(req, res, next);
}

module.exports = { requireLogin, requireApiKeyOrLogin };
EOF
sed -i '' 's/const { requireLogin } = require(".\/auth");/const { requireApiKeyOrLogin } = require(".\/auth");/; s/app.get("\/admin\/reports", requireLogin,/app.get("\/admin\/reports", requireApiKeyOrLogin,/' server.js
cat server.js
npm ls express >/dev/null 2>&1 || npm install --silent >/dev/null 2>&1
PORT=3911 REPORTS_API_KEY=s3cret node server.js & sleep 1
for h in "" "-H x-api-key:s3cret" "-H x-api-key:wrong" "-H Cookie:session=abc"; do echo "$h -> $(curl -s -o /dev/null -w '%{http_code}' $h localhost:3911/admin/reports)"; done
kill %1

